  `ASYS_TYPE` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'This should contain ''I'' for source systems connecting to CamelOne platform for inbound messages and ''O'' for target systems that CamelOne platform is connecting for ourbound messages.',
  `ASYS_URI_PART_1` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'For ASYS_TYPE of ''O'' this should be used to contain the unique locator of the endpoint - domain or IP address - eg. ''https://110.92.122.18/.\nFor ASYS_TYPE of ''I'' this should be used to store the allowable starting IP address of the system connecting to CamelOne\n',
  `ASYS_URI_PART_2` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL COMMENT 'For ASYS_TYPE of ''O'' this should contain the second part of the URI, eg. getsomething=xxxx?\nFor ASYS_TYPE of ''I'' this should contain the allowable end IP address of the system connecting to CamelOne',
  `ASYS_URI_PART_3` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ASYS_USER` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ASYS_URI_PASS` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ASYS_MTGR_LEVEL_1_CNTR` int DEFAULT NULL COMMENT 'Level 1 counter for auto-retrigger  in the case of outbound service.',
  `ASYS_MTGR_LEVEL_2_CNTR` int DEFAULT NULL COMMENT 'Level 2 counter for auto-retrigger  in the case of outbound service.',
  `ASYS_MTGR_LEVEL_3_CNTR` int DEFAULT NULL COMMENT 'Level 3 counter for auto-retrigger in the case of outbound service.',
  `ASYS_URI_TIMEOUT_CONNECTION` int DEFAULT NULL,
  `ASYS_URI_TIMEOUT_REQUEST` int DEFAULT NULL,
  `ASYS_STATUS` char(1) DEFAULT NULL COMMENT 'Account Sys Status',
  `ASYS_DT_CREATE` datetime DEFAULT NULL COMMENT 'Created date',
  `ASYS_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'Created by UID',
  `ASYS_DT_LUPD` datetime DEFAULT NULL COMMENT 'Updated date',
  `ASYS_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Updated by UID',
  PRIMARY KEY (`ASYS_ACCNID`,`ASYS_EP_ID`),
  KEY `NDX_FK_ASYS_ACCN` (`ASYS_ACCNID`),
  CONSTRAINT `FK_ASYS_ACCNID` FOREIGN KEY (`ASYS_ACCNID`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table contains information pertaining to the system end-points operated by the Accounts that CamelOne is integrating with. ASYS_URI_PART_1 will typically contain the domain or IP address of the end-point. ASYS_URI_PART_2 is to contain any other parts or parameters and can be left blank.There can be more than one end-points for each account indicated by ASYS_EP_IT.';
