--
-- Table structure for table `T_CORE_ALERTS`
--

DROP TABLE IF EXISTS `T_CORE_ALERTS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_ALERTS` (
  `ALRT_ACCNID` varchar(35) NOT NULL COMMENT 'Contains Account ID that the alert is for,\n‘SYSTEM’ if alerts are system related and not tied to any account. ',
  `ALRT_ID` varchar(35) NOT NULL COMMENT 'Contains the unique ID for this record.',
  `ALRT_SRC` varchar(35) NOT NULL COMMENT 'Contains the source ID of the particular module that generated the alert message. ',
  `ALRT_LEVEL` char(1) NOT NULL COMMENT 'Contains alert level to be sent. \n‘I’ – Information‘; \n‘W’ – Warning; \n‘C’- Critical\nDefault ‘I’\n',
  `ALRT_DEL_CHANNEL` char(1) NOT NULL COMMENT 'Channel of delivery to be used for this alert\n‘M’ – email; \n‘S’ – SMS;\nDefault ‘M’\n',
  `ALRT_MSG_1` varchar(4096) NOT NULL COMMENT 'The message content that needs to be sent.',
  `ALRT_MSG_2` varchar(4096) DEFAULT NULL COMMENT 'The supplementary message content',
  `ALRT_RCPT` varchar(4096) NOT NULL COMMENT 'List of recipients in comma separated format',
  `ALRT_STATUS` char(1) NOT NULL DEFAULT 'N' COMMENT 'Status of Alert message\n‘N’ – New;\n‘D’ - Delivered\n',
  `ALRT_DT_CREATED` datetime NOT NULL,
  `ALRT_DT_DELIVERED` datetime DEFAULT NULL,
  PRIMARY KEY (`ALRT_ID`),
  KEY `ALERT_STATUS_IDX` (`ALRT_STATUS`,`ALRT_DEL_CHANNEL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='This table stores the alerts that are meant to be sent out or published to the targeted contacts. This table will be read by a separate process/program that will generate the alerts.';
/*!40101 SET character_set_client = @saved_cs_client */;

